import React,{useState,useEffect} from 'react';
import {createRoot} from 'react-dom/client';
function App(){
 const [token,setToken]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState('');
 const [products,setProducts]=useState([]),[cart,setCart]=useState([]),[orders,setOrders]=useState([]),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Check the entered values');return d;}
 async function refresh(){setProducts(await api('/products'));if(token){setCart(await api('/cart'));setOrders(await api('/orders'));}}
 useEffect(()=>{refresh().catch(e=>setMessage(e.message));},[token]);
 async function act(fn){setBusy(true);setMessage('');try{await fn();}catch(e){setMessage(e.message);}finally{setBusy(false);}}
 const money=n=>'$'+(n/100).toFixed(2);
 return <main style={{maxWidth:900,margin:'40px auto',padding:24,fontFamily:'system-ui',color:'#17372e'}}><h1>Commerce Studio</h1><p>Local classroom store · seeded catalogue · payments disabled</p>
 {!token?<form onSubmit={e=>{e.preventDefault();act(async()=>{const d=await api('/users/login','POST',{email,password});setToken(d.session_token);setPassword('');});}}><h2>Welcome</h2><label>Email <input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label>{' '}<label>Password <input type="password" required minLength={12} value={password} onChange={e=>setPassword(e.target.value)}/></label><p><button disabled={busy}>Sign in</button>{' '}<button type="button" disabled={busy} onClick={()=>act(async()=>{await api('/users','POST',{email,password});setMessage('Account created. Sign in to continue.');})}>Create account</button></p></form>:<button onClick={()=>act(async()=>{await api('/logout','POST');setToken('');setCart([]);setOrders([]);})}>Sign out</button>}
 {message&&<p role="status" style={{background:'#f3ead4',padding:15}}>{message}</p>}<h2>Products</h2><section style={{display:'flex',gap:16,flexWrap:'wrap'}}>{products.map(p=><article key={p.id} style={{border:'1px solid #bdd5cb',borderRadius:12,padding:20}}><h3>{p.name}</h3><p>{money(p.price_cents)} · {p.stock} in stock</p><button disabled={!token||busy||!p.stock} onClick={()=>act(async()=>{await api('/cart','POST',{product_id:p.id,quantity:1});await refresh();})}>Add to cart</button></article>)}</section>
 {token&&<><h2>Your cart</h2>{cart.length===0?<p>Your cart is empty.</p>:cart.map(i=><p key={i.product_id}>{i.name} × {i.quantity} — {money(i.price_cents*i.quantity)} {' '}<button disabled={busy} onClick={()=>act(async()=>{await api('/cart/'+i.product_id,'DELETE');await refresh();})}>Remove</button></p>)}<button disabled={busy||!cart.length} onClick={()=>act(async()=>{await api('/orders','POST');await refresh();setMessage('Order recorded. No payment has been collected.');})}>Place demo order</button><h2>Your orders</h2>{orders.map(o=><p key={o.id}>Order {o.id} · {money(o.total_cents)} · {o.created_at} {' '}<button disabled={busy} onClick={()=>act(()=>api('/payment','POST',{order_id:o.id}))}>Check payment availability</button></p>)}</>}
 <p style={{marginTop:40}}>Teaching slice: single-session accounts, local SQLite, no admin interface or live payment integration. Do not use with real customer data.</p></main>;
}
createRoot(document.getElementById('root')).render(<App/>);

