{
  "name": "frontend",
  "version": "1.0.0",
  "description": "React frontend for the e-commerce demo",
  "main": "index.html",
  "scripts": {
    "start": "react-scripts start"
  },
  "dependencies": {
    "react": "18.2.0",
    "react-dom": "18.2.0",
    "react-scripts": "5.0.1"
  }
}

import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';

function App() {
  const [user, setUser] = useState(null);
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [paymentIntent, setPaymentIntent] = useState(null);
  const [error, setError] = useState(null);

  const registerUser = async (email, password) => {
    try {
      const response = await fetch('/api/users', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ email, password })
      });
      const data = await response.json();
      if (response.ok) {
        alert('Registration successful!');
      } else {
        alert('Registration failed: ' + data.detail);
      }
    } catch (err) {
      setError('Registration error: ' + err.message);
    }
  };

  const loginUser = async (email, password) => {
    try {
      const response = await fetch('/api/users/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ email, password })
      });
      const data = await response.json();
      if (response.ok) {
        setUser({ id: data.user_id, token: data.session_token });
        alert('Login successful!');
      } else {
        alert('Login failed: ' + data.detail);
      }
    } catch (err) {
      setError('Login error: ' + err.message);
    }
  };

  const getProducts = async () => {
    try {
      const response = await fetch('/api/products');
      const data = await response.json();
      if (response.ok) {
        setProducts(data);
      } else {
        alert('Failed to fetch products: ' + data.detail);
      }
    } catch (err) {
      setError('Product fetch error: ' + err.message);
    }
  };

  const addToCart = async (product) => {
    if (!user) {
      alert('Please log in to add items to your cart');
      return;
    }
    try {
      const response = await fetch('/api/cart', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + user.token
        },
        body: JSON.stringify({ product_id: product.id, quantity: 1 })
      });
      if (response.ok) {
        alert('Item added to cart');
        setCart([...cart, { ...product, quantity: 1 }]);
      } else {
        alert('Failed to add item to cart: ' + (await response.json()).detail);
      }
    } catch (err) {
      setError('Cart update error: ' + err.message);
    }
  };

  const removeFromCart = async (product) => {
    if (!user) {
      alert('Please log in to remove items from your cart');
      return;
    }
    try {
      const response = await fetch('/api/cart/' + product.id, {
        method: 'DELETE',
        headers: {
          'Authorization': 'Bearer ' + user.token
        }
      });
      if (response.ok) {
        alert('Item removed from cart');
        setCart(cart.filter(item => item.id !== product.id));
      } else {
        alert('Failed to remove item from cart: ' + (await response.json()).detail);
      }
    } catch (err) {
      setError('Cart update error: ' + err.message);
    }
  };

  const createOrder = async () => {
    if (!user || cart.length === 0) {
      alert('Please log in and add items to your cart before creating an order');
      return;
    }
    try {
      const response = await fetch('/api/orders', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + user.token
        }
      });
      const data = await response.json();
      if (response.ok) {
        alert('Order created successfully!');
        setOrders([...orders, { id: data.id, total_cents: data.total_cents, created_at: new Date().toISOString() }]);
        setCart([]);
      } else {
        alert('Failed to create order: ' + (await response.json()).detail);
      }
    } catch (err) {
      setError('Order creation error: ' + err.message);
    }
  };

  const getOrders = async () => {
    if (!user) {
      alert('Please log in to view your order history');
      return;
    }
    try {
      const response = await fetch('/api/orders', {
        method: 'GET',
        headers: {
          'Authorization': 'Bearer ' + user.token
        }
      });
      const data = await response.json();
      if (response.ok) {
        setOrders(data);
      } else {
        alert('Failed to fetch order history: ' + (await response.json()).detail);
      }
    } catch (e) {
      setError('Order fetch error: ' + e.message);
    }
  };

  const processPayment = async (order) => {
    if (!user) {
      alert('Please log in to process payment');
      return;
    }
    try {
      const response = await fetch('/api/payment', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + user.token
        },
        body: JSON.stringify({ order_id: order.id })
      });
      const data = await response.json();
      if (response.ok) {
        alert('Payment intent created successfully!');
        setPaymentIntent(data);
      } else {
        alert('Failed to create payment intent: ' + (await response.json()).detail);
      }
    } catch (err) {
      setError('Payment processing error: ' + err.message);
    }
  };

  const logout = async () => {
    if (!user) {
      alert('You are not logged in');
      return;
    }
    try {
      const response = await fetch('/api/logout', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + user.token
        }
      });
      if (response.ok) {
        setUser(null);
        alert('Logged out successfully!');
      } else {
        alert('Failed to log out: ' + (await response.json()).detail);
      }
    } catch (err) {
      setError('Logout error: ' + err.message);
    }
  };

  useEffect(() => {
    getProducts();
    getOrders();
  }, []);

  return (
    <div>
      <h1>E-Commerce Demo</h1>
      {!user ? (
        <div>
          <h2>Register</h2>
          <input type="email" placeholder="Email" />
          <input type="password" placeholder="Password" />
          <button onClick={registerUser}>Register</button>
          <h2>Login</h2>
          <input type="email" placeholder="Email" />
          <input type="password" placeholder="Password" />
          <button onClick={loginUser}>Login</button>
        </div>
      ) : (
        <div>
          <h2>Products</h2>
          <ul>
            {products.map(product => (
              <li key={product.id}>
                <h3>{product.name}</h3>
                <p>Price: {product.price_cents / 100} USD</p>
                <p>Stock: {product.stock}</p>
                <button onClick={() => addToCart(product)}>Add to Cart</button>
              </li>
            ))}
          </ul>
          <h2>Cart</h2>
          <ul>
            {cart.map(item => (
              <li key={item.id}>
                <h3>{item.name}</h3>
                <p>Price: {item.price_cents / 100} USD</p>
                <p>Quantity: {item.quantity}</p>
                <button onClick={() => removeFromCart(item)}>Remove</button>
              </li>
            ))}
          </ul>
          <button onClick={createOrder}>Create Order</button>
          <h2>Orders</h2>
          <ul>
            {orders.map(order => (
              <li key={order.id}>
                <h3>Order {order.id}</h3>
                <p>Total: {order.total_cents / 100} USD</p>
                <p>Created at: {new Date(order.created_at).toLocaleString()}</p>
                <button onClick={() => processPayment(order)}>Process Payment</button>
              </li>
            ))}
          </ul>
          <button onClick={logout}>Logout</button>
        </div>
      )}
      {error && <p style={{ color: 'red' }}>{error}</p>}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);

